/* ===== NATIVE BROWSER UI THEME ===== */
@layer base {
  .dark {
    color-scheme: dark;
  }
}

/* ===== AUTOFILL UTILITIES ===== */
@utility autofill-bg-* {
  &:autofill {
    background-clip: padding-box;
    box-shadow:
      var(--tw-inset-shadow, 0 0 #0000),
      var(--tw-inset-ring-shadow, 0 0 #0000),
      var(--tw-ring-offset-shadow, 0 0 #0000),
      var(--tw-ring-shadow, 0 0 #0000),
      var(--tw-shadow, 0 0 #0000),
      inset 0 0 0 1000px --value(--color-*);
  }
}

@utility autofill-bg-transparent {
  &:autofill {
    -webkit-background-clip: text;
    background-clip: text;
  }
}

@utility autofill-text-* {
  &:autofill {
    color: --value(--color-*);
    -webkit-text-fill-color: --value(--color-*);
    caret-color: --value(--color-*);
  }
}

/* ===== SURFACE UTILITIES ===== */
@utility surface-* {
  --nx-surface: --value(--color-*);
}

@utility ring-surface {
  --tw-ring-color: var(--nx-surface, --theme(--color-background));
}

@utility ring-offset-surface {
  --tw-ring-offset-color: var(--nx-surface, --theme(--color-background));
}

/* ===== TARGET SIZE UTILITIES ===== */
@utility target-24 {
  &::before {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    width: max(100%, 24px);
    height: max(100%, 24px);
    translate: -50% -50%;
  }
}

/* Spacing role utilities — data-driven from canonical mode role tokens. */

@utility p-container {
  padding: var(--nx-container-p);
}

@utility gap-container {
  gap: var(--nx-container-gap);
}

@utility gap-layout-section {
  gap: var(--nx-layout-section-gap);
}

@utility gap-layout-stack {
  gap: var(--nx-layout-stack-gap);
}

