// Clicking the trigger expands the content and fires onOpenChange.
export const ClickInteraction: Story = {
  args: { onOpenChange: fn() },
  render: (args) => (
    <Collapsible
      onOpenChange={args.onOpenChange}
      className="nx:flex nx:w-72 nx:flex-col"
    >
      <CollapsibleTrigger asChild>
        <Button variant="outline">Toggle details</Button>
      </CollapsibleTrigger>
      <CollapsibleContent>
        <div className="nx:mt-2 nx:rounded-md nx:border-default nx:border-border-default nx:px-4 nx:py-2 nx:typography-label-default nx:text-foreground">
          Now you see me.
        </div>
      </CollapsibleContent>
    </Collapsible>
  ),
  play: async ({ canvasElement, args }) => {
    const canvas = within(canvasElement);
    const trigger = canvas.getByRole('button', { name: 'Toggle details' });
    await expect(trigger).toHaveAttribute('aria-expanded', 'false');
    await userEvent.click(trigger);
    await expect(args.onOpenChange).toHaveBeenCalledWith(true);
    await expect(trigger).toHaveAttribute('aria-expanded', 'true');
    await expect(canvas.getByText('Now you see me.')).toBeVisible();
  },
};

