const errorMessages: Record<Exclude<FilterErrorCode, 'tooDeep'>, string> = {
  duplicateId: 'Each condition and group needs a unique ID.',
  unknownField: 'Choose an available field.',
  unknownOperator: 'Choose an available operator.',
  unexpectedValue: 'This operator takes no value.',
  valueShape: 'Choose a value for this operator.',
  incompleteRange: 'Enter both ends of the range.',
  missingValue: 'Enter a value.',
  invalidNumber: 'Enter a valid number.',
  invalidDate: 'Enter a valid date.',
  unknownOption: 'Choose an available option.',
  reversedRange: 'The start must not be after the end.',
  emptyGroup: 'Add a condition or remove this group.',
};
function errorMessage(code: FilterErrorCode, maxDepth: number) {
  if (code === 'tooDeep')
    return `Use at most ${maxDepth} levels of nested groups.`;
  return errorMessages[code];
}

function nodeIds(node: FilterGroup | FilterRule): string[] {
  if (node.kind === 'rule') return [node.id];
  return [node.id, ...node.children.flatMap(nodeIds)];
}

// Restored trees can already hold IDs from an earlier page load, so skip any in use.
let nodeCount = 0;
function createNodeId(prefix: string, taken: ReadonlySet<string>) {
  let id: string;
  do {
    nodeCount += 1;
    id = `${prefix}${nodeCount}`;
  } while (taken.has(id));
  return id;
}

interface PickerProps<Value extends string> {
  className?: string;
  leading?: React.ReactNode;
  label: string;
  value: Value;
  options: readonly { value: Value; label: string }[];
  onValueChange: (value: Value) => void;
  disabled?: boolean;
  invalid?: boolean;
  describedBy?: string;
  triggerRef?: React.Ref<HTMLButtonElement>;
}
function Picker<Value extends string>({
  label,
  value,
  options,
  onValueChange,
  disabled,
  invalid,
  describedBy,
  triggerRef,
  className,
  leading,
}: PickerProps<Value>) {
  const available = options.some((option) => option.value === value);
  function select(next: string) {
    const option = options.find((item) => item.value === next);
    if (option) onValueChange(option.value);
  }
  return (
    <Select value={value} onValueChange={select} disabled={disabled}>
      <SelectTrigger
        ref={triggerRef}
        aria-label={label}
        aria-invalid={invalid}
        aria-describedby={describedBy}
        className={cn(
          'nx:min-h-(--nx-spacing-8) nx:w-auto nx:min-w-0 nx:max-w-full nx:px-2.5 nx:[&>span]:flex-1 nx:[&>span]:text-start',
          className
        )}
      >
        {leading}
        <SelectValue placeholder="Choose…">
          {!available && value ? 'Unavailable selection' : undefined}
        </SelectValue>
      </SelectTrigger>
      <SelectContent className="nx:max-w-(--radix-select-content-available-width)">
        {options
          .filter((option) => option.value !== '')
          .map((option) => (
            <SelectItem key={option.value} value={option.value}>
              {option.label}
            </SelectItem>
          ))}
      </SelectContent>
    </Select>
  );
}
function MultipleValues({
  field,
  value,
  onValueChange,
  disabled,
  invalid,
  describedBy,
}: {
  field: Extract<FilterField, { type: 'choice' }>;
  value: string[];
  onValueChange: (value: string[]) => void;
  disabled?: boolean;
  invalid?: boolean;
  describedBy?: string;
}) {
  const id = React.useId();
  const [search, setSearch] = React.useState('');
  const options = field.options.filter((option) =>
    option.label.toLocaleLowerCase().includes(search.toLocaleLowerCase())
  );
  function toggle(option: string) {
    onValueChange(
      value.includes(option)
        ? value.filter((item) => item !== option)
        : [...value, option]
    );
  }
  const summary =
    value
      .map(
        (item) =>
          field.options.find((option) => option.value === item)?.label ?? item
      )
      .join(', ') || 'Choose values…';
  return (
    <Popover onOpenChange={() => setSearch('')}>
      <PopoverTrigger asChild>
        <Button
          size="sm"
          variant="outline"
          disabled={disabled}
          aria-label={`${field.label} values: ${summary}`}
          aria-invalid={invalid}
          aria-describedby={describedBy}
          className="nx:h-(--nx-spacing-8) nx:w-full nx:min-w-0 nx:justify-between"
        >
          <span className="nx:truncate">{summary}</span>
          <IconChevronDown aria-hidden="true" />
        </Button>
      </PopoverTrigger>
      <PopoverContent
        align="start"
        aria-label={`${field.label} values`}
        className="nx:w-64 nx:max-w-(--radix-popover-content-available-width) nx:overflow-hidden nx:p-0"
      >
        <div className="nx:border-b nx:border-border-default nx:p-2">
          <Input
            size="sm"
            aria-label={`Search ${field.label} options`}
            placeholder="Search options…"
            value={search}
            disabled={disabled}
            onChange={(event) => setSearch(event.target.value)}
          />
        </div>
        <div className="nx:max-h-48 nx:overflow-y-auto nx:p-1">
          {options.map((option, index) => (
            <ChoiceRow
              key={option.value}
              htmlFor={`${id}-${index}`}
              className="nx:not-has-[:disabled]:hover:bg-popover-hover"
            >
              <Checkbox
                id={`${id}-${index}`}
                checked={value.includes(option.value)}
                disabled={disabled}
                onCheckedChange={() => toggle(option.value)}
              />
              <span className="nx:min-w-0 nx:break-words">{option.label}</span>
            </ChoiceRow>
          ))}
          {!options.length && (
            <p className="nx:m-0 nx:p-2 nx:typography-body-small nx:text-muted-foreground">
              No options found.
            </p>
          )}
        </div>
      </PopoverContent>
    </Popover>
  );
}
function RuleValue({
  field,
  rule,
  onValueChange,
  disabled,
  errorId,
  invalid,
}: {
  field: FilterField;
  rule: FilterRule;
  onValueChange: (rule: FilterRule) => void;
  disabled?: boolean;
  errorId?: string;
  invalid: boolean;
}) {
  if (rule.operator === 'isEmpty' || rule.operator === 'isNotEmpty')
    return (
      <span className="nx:self-center nx:typography-body-small nx:text-muted-foreground">
        No value needed
      </span>
    );
  if (rule.operator === 'isAnyOf' || rule.operator === 'isNoneOf') {
    if (field.type !== 'choice') return null;
    return (
      <MultipleValues
        field={field}
        value={rule.value}
        onValueChange={(value) => onValueChange({ ...rule, value })}
        disabled={disabled}
        invalid={invalid}
        describedBy={errorId}
      />
    );
  }
  if (rule.operator === 'between') {
    if (field.type === 'choice') return null;
    const [start, end] = rule.value;
    const changeStart = (event: React.ChangeEvent<HTMLInputElement>) =>
      onValueChange({ ...rule, value: [event.target.value, end] });
    const changeEnd = (event: React.ChangeEvent<HTMLInputElement>) =>
      onValueChange({ ...rule, value: [start, event.target.value] });
    return (
      <div className="nx:flex nx:min-w-0 nx:max-w-full nx:flex-wrap nx:items-center nx:gap-2 nx:@lg/rule:flex-nowrap nx:@lg/rule:gap-0 nx:@lg/rule:[&>input]:flex-1 nx:@lg/rule:[&>input:first-child]:rounded-e-none">
        <Input
          size="sm"
          type={field.type}
          step={field.type === 'number' ? 'any' : undefined}
          aria-label={`${field.label} start`}
          placeholder="From"
          value={start}
          onChange={changeStart}
          disabled={disabled}
          aria-invalid={invalid}
          aria-describedby={errorId}
          className="nx:min-w-0 nx:w-36 nx:max-w-full nx:typography-body-default nx:h-(--nx-spacing-8)"
        />
        <Input
          size="sm"
          type={field.type}
          step={field.type === 'number' ? 'any' : undefined}
          aria-label={`${field.label} end`}
          placeholder="To"
          value={end}
          onChange={changeEnd}
          disabled={disabled}
          aria-invalid={invalid}
          aria-describedby={errorId}
          className="nx:min-w-0 nx:w-36 nx:max-w-full nx:typography-body-default nx:h-(--nx-spacing-8)"
        />
      </div>
    );
  }
  if (field.type === 'choice')
    return (
      <Picker
        className="nx:w-full nx:bg-container"
        label={`${field.label} value`}
        options={field.options}
        value={rule.value}
        onValueChange={(value) => onValueChange({ ...rule, value })}
        disabled={disabled}
        invalid={invalid}
        describedBy={errorId}
      />
    );
  return (
    <Input
      size="sm"
      type={field.type}
      step={field.type === 'number' ? 'any' : undefined}
      aria-label={`${field.label} value`}
      placeholder={field.type === 'date' ? undefined : 'Enter a value…'}
      value={rule.value}
      onChange={(event) =>
        onValueChange({ ...rule, value: event.target.value })
      }
      disabled={disabled}
      aria-invalid={invalid}
      aria-describedby={errorId}
      className="nx:min-w-0 nx:w-full nx:max-w-full nx:bg-container nx:typography-body-default nx:h-(--nx-spacing-8)"
    />
  );
}
interface RuleEditorProps {
  value: FilterRule;
  fields: readonly FilterField[];
  onValueChange: (value: FilterRule) => void;
  onRemove: () => void;
  disabled?: boolean;
  error?: string;
  focusRef?: React.Ref<HTMLButtonElement>;
}
/** Edits one controlled condition; numeric and date operands remain draft strings. */
function FilterRuleEditor({
  value,
  fields,
  onValueChange,
  onRemove,
  disabled,
  error,
  focusRef,
}: RuleEditorProps) {
  const errorId = React.useId();
  const field = fields.find((item) => item.id === value.field);
  const operators = field ? getFilterOperators(field) : [];
  function changeField(fieldId: string) {
    const nextField = fields.find((item) => item.id === fieldId);
    if (!nextField) return;
    const operator = getFilterOperators(nextField)[0];
    if (!operator) return;
    onValueChange(emptyFilterRule(value.id, fieldId, operator));
  }
  function changeOperator(operator: FilterOperator) {
    onValueChange(changeFilterOperator(value, operator));
  }
  return (
    <div
      data-slot="filter-rule-editor"
      className="nx:@container/rule nx:min-w-0"
    >
      <div className="nx:flex nx:min-w-0 nx:items-start nx:gap-1">
        <div className="nx:grid nx:min-w-0 nx:flex-1 nx:grid-cols-1 nx:gap-1.5 nx:@sm/rule:grid-cols-2 nx:@lg/rule:gap-0 nx:@lg/rule:grid-cols-[minmax(0,1fr)_max-content_minmax(0,1.3fr)] nx:[&_button:focus-visible]:relative nx:[&_button:focus-visible]:z-10 nx:[&_input:focus-visible]:relative nx:[&_input:focus-visible]:z-10">
          <Picker
            className="nx:w-full nx:bg-container nx:@lg/rule:rounded-e-none"
            leading={field ? fieldIcons[field.type] : undefined}
            label="Field"
            value={value.field}
            options={fields
              .filter((item) => getFilterOperators(item).length)
              .map((item) => ({ value: item.id, label: item.label }))}
            onValueChange={changeField}
            disabled={disabled}
            triggerRef={focusRef}
            invalid={!field}
            describedBy={error ? errorId : undefined}
          />
          <Picker
            className={cn(
              'nx:w-full nx:@lg/rule:rounded-s-none nx:@lg/rule:border-s-0',
              !isValuelessOperator(value.operator) &&
                'nx:@lg/rule:rounded-e-none'
            )}
            label={`${field?.label ?? 'Condition'} operator`}
            value={value.operator}
            options={operators.map((operator) => ({
              value: operator,
              label: filterOperatorLabels[operator],
            }))}
            onValueChange={changeOperator}
            disabled={disabled || !field}
            invalid={!operators.includes(value.operator)}
            describedBy={error ? errorId : undefined}
          />
          {field && (
            <div className="nx:min-w-0 nx:@sm/rule:col-span-2 nx:@lg/rule:col-span-1 nx:@lg/rule:[&_input]:rounded-s-none nx:@lg/rule:[&_input]:border-s-0 nx:@lg/rule:[&_button]:rounded-s-none nx:@lg/rule:[&_button]:border-s-0">
              <RuleValue
                field={field}
                rule={value}
                onValueChange={onValueChange}
                disabled={disabled}
                errorId={error ? errorId : undefined}
                invalid={!!error}
              />
            </div>
          )}
        </div>
        <Button
          variant="ghost"
          size="sm"
          iconOnly
          startIcon={<IconX />}
          className="nx:size-(--nx-spacing-8) nx:shrink-0 nx:text-muted-foreground"
          disabled={disabled}
          onClick={onRemove}
        >
          {`Remove ${field?.label ?? 'unavailable'} condition`}
        </Button>
      </div>
      {error && (
        <p
          id={errorId}
          className="nx:mt-1 nx:mb-0 nx:typography-body-small nx:text-error-subtle-foreground"
        >
          {error}
        </p>
      )}
    </div>
  );
}
interface GroupEditorProps {
  value: FilterGroup;
  fields: readonly FilterField[];
  onValueChange: (value: FilterGroup) => void;
  onRemove?: () => void;
  disabled?: boolean;
  depth: number;
  maxDepth: number;
  errors: ReturnType<typeof getFilterErrors>;
  label: string;
  createId: (kind: FilterRule['kind'] | FilterGroup['kind']) => string;
  onRuleEdited: (id: string) => void;
}
function GroupEditor({
  value,
  fields,
  onValueChange,
  onRemove,
  disabled,
  depth,
  maxDepth,
  errors,
  label,
  createId,
  onRuleEdited,
}: GroupEditorProps) {
  const addRef = React.useRef<HTMLButtonElement>(null);
  const focusId = React.useRef<string | null>(null);
  const firstField = fields.find((field) => getFilterOperators(field).length);
  const groupError = errors.find((error) => error.id === value.id)?.code;
  function newRule(): FilterRule {
    const operator = firstField
      ? (getFilterOperators(firstField)[0] ?? 'is')
      : 'is';
    return emptyFilterRule(createId('rule'), firstField?.id ?? '', operator);
  }
  function addRule() {
    const rule = newRule();
    focusId.current = rule.id;
    onValueChange({ ...value, children: [...value.children, rule] });
  }
  function addGroup() {
    const group: FilterGroup = {
      kind: 'group',
      id: createId('group'),
      conjunction: 'any',
      children: [newRule()],
    };
    focusId.current = group.id;
    onValueChange({ ...value, children: [...value.children, group] });
  }
  function replace(next: FilterGroup | FilterRule) {
    if (next.kind === 'rule') onRuleEdited(next.id);
    onValueChange({
      ...value,
      children: value.children.map((child) =>
        child.id === next.id ? next : child
      ),
    });
  }
  function remove(id: string) {
    onValueChange({
      ...value,
      children: value.children.filter((child) => child.id !== id),
    });
    addRef.current?.focus();
  }
  function ruleError(id: string) {
    const code = errors.find((error) => error.id === id)?.code;
    return code && errorMessage(code, maxDepth);
  }
  function focusNewGroup(node: HTMLDivElement | null) {
    if (!node || focusId.current !== node.dataset.nodeId) return;
    node.querySelector<HTMLButtonElement>('button[role="combobox"]')?.focus();
    focusId.current = null;
  }
  return (
    <div
      data-slot="filter-group"
      role="group"
      aria-label={label}
      className={cn(
        'nx:min-w-0',
        depth > 0 &&
          'nx:rounded-md nx:border-default nx:border-border-default nx:bg-muted-extralight nx:p-3'
      )}
    >
      <div className="nx:mb-3 nx:flex nx:items-center nx:gap-2">
        <div className="nx:flex nx:min-w-0 nx:flex-1 nx:flex-wrap nx:items-center nx:gap-2">
          <span className="nx:shrink-0 nx:@2xl/builder:w-12 nx:typography-body-default nx:text-muted-foreground">
            Match
          </span>
          <div className="nx:shrink-0">
            <Picker
