function TypingIndicatorExample() {
  const [typing, setTyping] = React.useState(false);

  return (
    <div className={cn(column, 'nx:flex nx:flex-col nx:gap-4')}>
      <MessageGroup announce>
        <Message>
          <MessageAvatar>
            <AvatarFallback>AB</AvatarFallback>
