/* Indeterminate sweep keyframe for the Progress indicator, registered the way
 * tw-animate-css registers its own (@theme inline so the named utility compiles
 * without emitting a :root var). Imported by src/index.css. */
@theme inline {
  --animate-progress-indeterminate: nx-progress-indeterminate 1.5s ease-in-out
    infinite;

  @keyframes nx-progress-indeterminate {
    from {
      transform: translateX(-100%);
    }
    to {
      transform: translateX(300%);
    }
  }
}

import * as React from 'react';

import * as ProgressPrimitive from '@radix-ui/react-progress';

import { cn } from '../../lib/utils';

/**
 * Props for the Progress component.
 */
type ProgressProps = React.ComponentProps<typeof ProgressPrimitive.Root>;

/**
 * Bar that shows task progress from `value` 0 to 100, or an animated bar
 * without `value`. Always pass an `aria-label` or `aria-labelledby`.
 */
function Progress({ className, value, ...props }: ProgressProps) {
  return (
    <ProgressPrimitive.Root
      data-slot="progress"
      value={value}
      className={cn(
        'nx:relative nx:h-2 nx:w-full nx:overflow-hidden nx:rounded-full nx:bg-control-background',
        className
      )}
      {...props}
    >
      <ProgressPrimitive.Indicator
        data-slot="progress-indicator"
        className="nx:h-full nx:w-full nx:bg-primary-background nx:transition-transform nx:duration-fast nx:data-[state=indeterminate]:w-1/3 nx:data-[state=indeterminate]:animate-progress-indeterminate"
        style={
          value == null
            ? undefined
            : { transform: `translateX(-${100 - value}%)` }
        }
      />
    </ProgressPrimitive.Root>
  );
}

export { Progress, type ProgressProps };

