// Arrow keys on the focused separator resize the panels (aria-valuenow moves).
export const KeyboardInteraction: Story = {
  render: () => (
    <ResizablePanelGroup
      orientation="horizontal"
      className={groupClass}
      style={groupStyle}
    >
      <ResizablePanel defaultSize={50} style={panelStyle}>
