const overlayContentTransitionClassName = [
  'nx:transition-[opacity,scale]',
  'nx:duration-default',
  'nx:ease-move',
  'nx:data-[state=closed]:scale-95',
  'nx:data-[state=closed]:opacity-0',
  overlayPresenceExitClassName,
].join(' ');

const overlayScrimTransitionClassName = [
  'nx:transition-opacity',
  'nx:duration-default',
  'nx:ease-move',
  'nx:data-[state=closed]:opacity-0',
  overlayPresenceExitClassName,
].join(' ');

const overlayPanelTransitionClassName = [
  'nx:transition-[translate]',
  'nx:duration-slow',
  'nx:ease-move',
  overlayPresenceExitClassName,
].join(' ');

const overlayContentVariants = cva(
  [
    // Centred with margins, not a translate: a transform would make this the
    // containing block for fixed-position popups a dialog holds.
    'nx:fixed nx:inset-0 nx:z-modal nx:m-auto nx:flex nx:h-fit nx:w-full nx:max-w-lg nx:flex-col',
    'nx:max-h-[calc(100svh-2rem)] nx:overflow-hidden',
    'nx:gap-4 nx:border-default nx:border-border-default nx:bg-container nx:py-6 nx:shadow-lg',
    overlayContentTransitionClassName,
    'nx:sm:rounded-lg',
  ].join(' ')
);

const overlayScrimVariants = cva(
  [
    'nx:fixed nx:inset-0 nx:z-modal nx:bg-overlay',
    overlayScrimTransitionClassName,
  ].join(' ')
);

const overlayHeaderVariants = cva(
  'nx:flex nx:shrink-0 nx:flex-col nx:gap-1 nx:px-6',
  {
    variants: {
      variant: {
        default: 'nx:text-center nx:sm:text-left',
        center: 'nx:items-center nx:text-center',
      },
    },
    defaultVariants: {
      variant: 'default',
    },
  }
);

const overlayBodyClassName = [
  'nx:min-h-0',
  'nx:overflow-y-auto',
  'nx:px-6',
  'nx:focus-visible:outline-2',
  'nx:focus-visible:outline-focus-default',
  'nx:focus-visible:[outline-offset:-2px]',
].join(' ');

const overlayFooterVariants = cva('nx:flex nx:shrink-0 nx:gap-2 nx:px-6', {
  variants: {
    orientation: {
      horizontal:
        'nx:flex-col nx:sm:flex-row nx:sm:items-center nx:sm:justify-end',
      vertical: 'nx:flex-col nx:items-stretch nx:*:w-full',
    },
  },
  defaultVariants: {
    orientation: 'horizontal',
  },
});

const overlayCloseButtonClassName = [
  'nx:absolute nx:target-24 nx:right-6 nx:top-6 nx:rounded-sm nx:border-0 nx:bg-transparent nx:p-1 nx:text-muted-foreground-subtle',
  'nx:transition-control',
  'nx:hover:bg-container-hover nx:hover:text-foreground',
  'nx:focus-visible:bg-container-hover nx:focus-visible:text-foreground',
  'nx:focus-visible:outline-2 nx:focus-visible:outline-focus-default',
  'nx:disabled:pointer-events-none',
].join(' ');

type OverlayVariant = NonNullable<
  VariantProps<typeof overlayHeaderVariants>['variant']
>;

type OverlayButtonOrientation = NonNullable<
  VariantProps<typeof overlayFooterVariants>['orientation']
>;

type OverlayLayoutContextValue = {
  variant: OverlayVariant;
  buttonOrientation: OverlayButtonOrientation;
};

const defaultOverlayLayout: OverlayLayoutContextValue = {
  variant: 'default',
  buttonOrientation: 'horizontal',
};

function resolveOverlayButtonOrientation(
  variant: OverlayVariant
): OverlayButtonOrientation {
  return variant === 'center' ? 'vertical' : 'horizontal';
}

function containsComposedSlot(
  children: React.ReactNode,
  slot: React.ElementType
): boolean {
  return React.Children.toArray(children).some((child) => {
    if (!React.isValidElement(child)) return false;
    if (child.type === slot) return true;
    if (child.type === React.Fragment) {
      const fragment = child as React.ReactElement<{
        children?: React.ReactNode;
      }>;
      return containsComposedSlot(fragment.props.children, slot);
    }
    return false;
  });
}

export {
  containsComposedSlot,
  defaultOverlayLayout,
  menuItemInsetClassName,
  navigationMenuInlinePopoverSurfaceClassName,
  navigationMenuInlinePopoverTransitionClassName,
  overlayBodyClassName,
  type OverlayButtonOrientation,
  overlayCloseButtonClassName,
  overlayContentVariants,
  overlayFloatingTransitionClassName,
  overlayFooterVariants,
  overlayHeaderVariants,
  type OverlayLayoutContextValue,
  overlayPanelTransitionClassName,
  overlayScrimTransitionClassName,
  overlayScrimVariants,
  type OverlayVariant,
  popoverSurfaceClassName,
  resolveOverlayButtonOrientation,
  tooltipSurfaceClassName,
};

import * as React from 'react';

import * as DialogPrimitive from '@radix-ui/react-dialog';
import { cva, type VariantProps } from 'class-variance-authority';

import { IconX } from '../../lib/icons';
import { cn } from '../../lib/utils';
import {
  overlayBodyClassName,
  overlayCloseButtonClassName,
  overlayPanelTransitionClassName,
  overlayScrimTransitionClassName,
} from '../overlay-layout/overlay-layout';

/**
 * Root of a panel that slides in from an edge of the viewport. Holds the open
 * state.
 */
const Sheet = DialogPrimitive.Root;

/**
 * Opens the sheet. Set `asChild` to render your own element.
 */
const SheetTrigger = DialogPrimitive.Trigger;

/**
 * Renders the sheet content into `document.body`.
 */
const SheetPortal = DialogPrimitive.Portal;

/**
 * Closes the sheet. Set `asChild` to render your own element.
 */
const SheetClose = DialogPrimitive.Close;

/**
 * Props for SheetOverlay.
 */
type SheetOverlayProps = React.ComponentProps<typeof DialogPrimitive.Overlay>;

/**
 * Dimmed layer behind the sheet.
 */
function SheetOverlay({ className, ...props }: SheetOverlayProps) {
  return (
    <DialogPrimitive.Overlay
      data-slot="sheet-overlay"
      className={cn(
        'nx:fixed nx:inset-0 nx:z-modal nx:bg-overlay',
        overlayScrimTransitionClassName,
        className
      )}
      {...props}
    />
  );
}

/**
 * Per-side positioning and slide motion for the sheet panel. Each side pins the
 * panel to an edge, and a closed panel translates 100% past that edge.
 */
const sheetContentVariants = cva(
  cn(
    'nx:fixed nx:z-modal nx:flex nx:flex-col nx:overflow-hidden',
    'nx:bg-container nx:shadow-lg',
    overlayPanelTransitionClassName
  ),
  {
    variants: {
      side: {
        top: cn(
          'nx:inset-x-0 nx:top-0 nx:h-auto nx:max-h-svh nx:border-b-default nx:border-border-default',
          'nx:data-[state=closed]:-translate-y-full'
        ),
        bottom: cn(
          'nx:inset-x-0 nx:bottom-0 nx:h-auto nx:max-h-svh nx:border-t-default nx:border-border-default',
          'nx:data-[state=closed]:translate-y-full'
        ),
        left: cn(
          'nx:left-0 nx:top-0 nx:h-svh nx:w-3/4 nx:border-r-default nx:border-border-default nx:sm:max-w-sm',
          'nx:data-[state=closed]:-translate-x-full'
        ),
        right: cn(
          'nx:right-0 nx:top-0 nx:h-svh nx:w-3/4 nx:border-l-default nx:border-border-default nx:sm:max-w-sm',
          'nx:data-[state=closed]:translate-x-full'
        ),
      },
    },
    defaultVariants: {
      side: 'right',
    },
  }
);

/**
 * Props for SheetContent.
 */
interface SheetContentProps
  extends
    React.ComponentProps<typeof DialogPrimitive.Content>,
    VariantProps<typeof sheetContentVariants> {
  /**
   * Shows the close button in the top-right corner.
   */
  showCloseButton?: boolean;
}

/**
 * The sliding panel, rendered in a portal with an overlay. `side` picks the
 * edge it slides from.
 */
function SheetContent({
  className,
  children,
  side = 'right',
  showCloseButton = true,
  ...props
}: SheetContentProps) {
  return (
    <SheetPortal>
      <SheetOverlay />
      <DialogPrimitive.Content
        data-slot="sheet-content"
        data-side={side}
        className={cn(sheetContentVariants({ side }), className)}
        {...props}
      >
        {children}
        {showCloseButton && (
          <DialogPrimitive.Close
            data-slot="sheet-close-button"
            className={overlayCloseButtonClassName}
          >
            <IconX className="nx:size-icon-glyph-default nx:icon-stroke" />
            <span className="nx:sr-only">Close</span>
          </DialogPrimitive.Close>
        )}
      </DialogPrimitive.Content>
    </SheetPortal>
  );
}

/**
 * Props for SheetHeader.
 */
type SheetHeaderProps = React.ComponentProps<'div'>;

/**
 * Holds the title and description.
 */
function SheetHeader({ className, ...props }: SheetHeaderProps) {
  return (
    <div
      data-slot="sheet-header"
      className={cn(
        'nx:flex nx:shrink-0 nx:flex-col nx:gap-1 nx:p-6',
        className
      )}
      {...props}
    />
  );
}

/**
 * Props for SheetBody.
 */
type SheetBodyProps = React.ComponentProps<'div'>;

/**
 * Main content between the header and footer. Its side padding matches
 * SheetHeader and SheetFooter.
 */
function SheetBody({ className, ...props }: SheetBodyProps) {
  return (
    <div
      data-slot="sheet-body"
      className={cn(overlayBodyClassName, className)}
      // Overlay bodies own the scroll region, so pure-text overflow must be keyboard reachable.
      tabIndex={0}
      {...props}
    />
  );
}

/**
 * Props for SheetFooter.
 */
type SheetFooterProps = React.ComponentProps<'div'>;

/**
 * Holds the action buttons, pinned to the bottom of the panel.
 */
function SheetFooter({ className, ...props }: SheetFooterProps) {
  return (
    <div
      data-slot="sheet-footer"
      className={cn(
        'nx:mt-auto nx:flex nx:shrink-0 nx:flex-col nx:gap-2 nx:p-6',
        className
      )}
      {...props}
    />
  );
}

/**
 * Props for SheetTitle.
 */
type SheetTitleProps = React.ComponentProps<typeof DialogPrimitive.Title>;

/**
 * Title of the sheet. Place it inside SheetHeader.
 */
function SheetTitle({ className, ...props }: SheetTitleProps) {
  return (
    <DialogPrimitive.Title
      data-slot="sheet-title"
      className={cn('nx:m-0 nx:typography-heading-xsmall', className)}
      {...props}
    />
  );
}

/**
 * Props for SheetDescription.
 */
type SheetDescriptionProps = React.ComponentProps<
  typeof DialogPrimitive.Description
>;

/**
 * Supporting text under the title.
 */
function SheetDescription({ className, ...props }: SheetDescriptionProps) {
  return (
    <DialogPrimitive.Description
      data-slot="sheet-description"
      className={cn(
        'nx:m-0 nx:typography-body-default nx:text-muted-foreground',
        className
      )}
      {...props}
    />
  );
}

export {
  Sheet,
  SheetBody,
  type SheetBodyProps,
  SheetClose,
  SheetContent,
  type SheetContentProps,
  sheetContentVariants,
  SheetDescription,
  type SheetDescriptionProps,
  SheetFooter,
  type SheetFooterProps,
  SheetHeader,
  type SheetHeaderProps,
  SheetOverlay,
  type SheetOverlayProps,
  SheetPortal,
  SheetTitle,
  type SheetTitleProps,
  SheetTrigger,
};

