interface SidebarMenuButtonProps
  extends
    React.ComponentProps<'button'>,
    VariantProps<typeof sidebarMenuButtonVariants> {
  /**
   * Renders the child element instead, such as a router link.
   */
  asChild?: boolean;
  /**
   * Marks the item as the current page.
   */
  isActive?: boolean;
  /**
   * Tooltip shown only on the icon rail. A string or `TooltipContent` props.
   */
  tooltip?: string | TooltipContentProps;
}

/**
 * Main clickable nav item. On the icon rail, `tooltip` shows the label on
 * hover.
 */
function SidebarMenuButton({
  asChild = false,
  isActive = false,
  variant = 'default',
  size = 'default',
  tooltip,
  className,
  ...props
}: SidebarMenuButtonProps) {
  const Comp = asChild ? Slot : 'button';
  const { isNarrow, state } = useSidebar();
  const [open, setOpen] = React.useState(false);
  const isRail = state === 'collapsed' && !isNarrow;
  // Only the icon rail shows the tooltip. Radix never reports a close after
  // the button leaves the rail.
  if (!isRail && open) setOpen(false);

  const button = (
    <Comp
      data-slot="sidebar-menu-button"
      data-variant={variant}
      data-size={size}
      data-active={isActive}
      aria-current={isActive ? 'page' : undefined}
      className={cn(sidebarMenuButtonVariants({ variant, size }), className)}
      {...props}
    />
  );

  if (!tooltip) {
    return button;
  }

  const tooltipProps =
    typeof tooltip === 'string' ? { children: tooltip } : tooltip;

  return (
    <Tooltip open={open} onOpenChange={setOpen}>
      <TooltipTrigger asChild>{button}</TooltipTrigger>
      <TooltipContent side="right" align="center" {...tooltipProps} />
    </Tooltip>
  );
}

