/**
 * Track the active theme by observing the `.dark` class on the document root
 * (where nxds toggles dark mode), or `data-theme="dark"` (where a Claude Design
 * page sets it), via MutationObserver, keeping sonner's own `theme` in sync
 * with the design system.
 */
function subscribeToTheme(notify: () => void) {
  const observer = new MutationObserver(notify);
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ['class', 'data-theme'],
  });
  return () => observer.disconnect();
}

function getThemeSnapshot(): 'light' | 'dark' {
  const root = document.documentElement;
  return root.classList.contains('dark') || root.dataset['theme'] === 'dark'
    ? 'dark'
    : 'light';
}

function useToasterTheme(): 'light' | 'dark' {
  return React.useSyncExternalStore(
    subscribeToTheme,
    getThemeSnapshot,
    () => 'light'
  );
}

/** nxds's internal icons in place of sonner's bundled set. */
const toasterIcons = {
  success: <IconCircleCheck className="nx:size-icon-glyph-default" />,
  info: <IconInfoCircle className="nx:size-icon-glyph-default" />,
  warning: <IconAlertTriangle className="nx:size-icon-glyph-default" />,
  error: <IconAlertCircle className="nx:size-icon-glyph-default" />,
