const InlineEditPencilTrigger = React.forwardRef<
  HTMLButtonElement,
  React.PropsWithoutRef<InlineEditTriggerProps>
>(function InlineEditPencilTrigger(propsWithoutRef, forwardedRef) {
  const {
    label,
    children,
    ...props
  }: React.PropsWithoutRef<InlineEditTriggerProps> & {
    ref?: React.ForwardedRef<HTMLButtonElement>;
  } =
    forwardedRef === null
      ? propsWithoutRef
      : { ...propsWithoutRef, ref: forwardedRef };
  return (
    <div className="nx:flex nx:items-center nx:gap-2">
      {children}
      <Button
        type="button"
        variant="ghost"
        size="sm"
        iconOnly
